"""Original formative MCQs aligned to the supplied weekly lecture-note sequence."""
import json, pathlib, collections
ROOT=pathlib.Path(__file__).resolve().parents[1]
questions=[]; week=7
names={7:'Testing and debugging',8:'Object-oriented programming',9:'Classes and inheritance',10:'Program efficiency I',11:'Program efficiency II',12:'Searching and sorting',13:'Python, MATLAB, C++ and Java',14:'Comprehensive course review'}
def Q(title, correct, wrong, explanation, code='', mode='concept'):
    n=sum(q['week']==week for q in questions)+1
    pos=len(questions)%4
    options=list(wrong);options.insert(pos,correct)
    assert len(options)==4 and len(set(options))==4,(week,n,title,options)
    questions.append(dict(id=f'sh-w{week}-{n:02}',topic=f'week{week}',week=week,title=title,code=code,options=options,answer=pos,explanation=explanation,bank='second-half',source=f'Week {week} · Original practice · {names[week]}',mode=mode))
def C(label,code,correct,wrong,explanation):
    Q(label+' — what is the complete printed output?',correct,wrong,explanation,code,'python-output')
def T(title,correct,a,b,c,explanation):Q(title,correct,[a,b,c],explanation)
# Week 7: testing, debugging, exceptions, assertions.
C('Boundary comparison','print([x >= 10 for x in [9, 10, 11]])','[False, True, True]',['[False, False, True]','[True, True, True]','[True, False, False]'],'The equality boundary is included by >=; 9 fails while 10 and 11 pass.')
C('Caught conversion',"try:\n    print(int('4.5'))\nexcept ValueError:\n    print('invalid')",'invalid',['4','4.5','ValueError'],'int does not parse a decimal-point string; the matching ValueError handler prints invalid.')
C('Finally after handling',"try:\n    x = 1 / 0\nexcept ZeroDivisionError:\n    print('recover')\nfinally:\n    print('cleanup')",'recover\ncleanup',['cleanup\nrecover','recover','cleanup'],'The division fails, the handler runs, and finally runs after the handler.')
C('Else on success',"try:\n    x = int('12')\nexcept ValueError:\n    print('bad')\nelse:\n    print(x + 1)",'13',['12','bad','No output'],'The conversion succeeds, so the else suite executes with x equal to 12.')
C('Assertion guard',"try:\n    assert -2 > 0, 'positive required'\n    print('ok')\nexcept AssertionError:\n    print('guard failed')",'guard failed',['ok','positive required\nok','No output'],'With assertions enabled, the false condition raises AssertionError before the next print.')
C('Rejected empty input',"def mean(xs):\n    if not xs:\n        raise ValueError('empty')\n    return sum(xs) / len(xs)\ntry:\n    mean([])\nexcept ValueError:\n    print('empty rejected')",'empty rejected',['0','None','ZeroDivisionError'],'The explicit empty-input check raises ValueError before division is attempted.')
C('Tracking a loop defect','total = 0\nfor x in [2, 4, 6]:\n    total = x\nprint(total)','6',['12','0','2'],'Assignment overwrites the accumulator on each iteration; the final value is 6.')
C('Testing approximate equality','import math\nprint(math.isclose(0.1 + 0.2, 0.3, abs_tol=1e-12))','True',['False','0.3','TypeError'],'isclose accepts the tiny floating-point difference under the stated tolerance.')
C('A trace of a repaired accumulator','total = 0\nfor x in [2, 4, 6]:\n    total += x\nprint(total)','12',['6','0','246'],'The accumulator adds all three values: 2 + 4 + 6 = 12.')
C('Different exception classes',"try:\n    print([3][2])\nexcept ValueError:\n    print('value')\nexcept IndexError:\n    print('index')",'index',['value','3','None'],'Index 2 is outside the one-element list, producing IndexError rather than ValueError.')
C('A missing mapping entry',"try:\n    print({'p': 8}['q'])\nexcept KeyError:\n    print('missing')",'missing',['8','None','q'],'Direct indexing of an absent dictionary key raises KeyError, which this handler catches.')
C('A default lookup',"print({'p': 8}.get('q', -1))",'-1',['None','8','KeyError'],'get returns the supplied default for a missing key without raising KeyError.')
C('A successful return with cleanup',"def f():\n    try:\n        return 7\n    finally:\n        print('done')\nprint(f())",'done\n7',['7\ndone','7','done\nNone'],'The finally suite prints before the pending return value is delivered to the caller.')
C('Testing mutation',"def add(xs):\n    xs.append(9)\na = [1]\nadd(a)\nprint(a)",'[1, 9]',['[1]','[9]','None'],'The parameter refers to the caller’s list, so append changes that list.')
C('Validation before calculation',"def ratio(a, b):\n    if b == 0:\n        return None\n    return a / b\nprint(ratio(4, 0))",'None',['0','4','ZeroDivisionError'],'The early return handles a zero denominator before division.')
C('A finite test set','tests = [0, 1, -1, 5]\nprint(sum(x >= 0 for x in tests))','3',['2','4','1'],'True counts as 1 in sum; zero, one and five satisfy the condition.')
C('Short circuit and safety','x = 0\nprint(x != 0 and 10 / x > 1)','False',['True','ZeroDivisionError','None'],'and stops after its false left operand, so the division is not evaluated.')
C('Exception scope',"def parse(s):\n    try:\n        return int(s)\n    except ValueError:\n        return -1\nprint(parse('bad'), parse('6'))",'-1 6',['bad 6','-1 -1','None 6'],'Only the first conversion fails; the successful second call returns 6.')
C('A test that exposes a sign bug','def magnitude(x):\n    return x\nprint(magnitude(-4) == 4)','False',['True','4','-4'],'The defective function returns -4, so comparison with the required magnitude 4 fails.')
C('Two passes through a handler',"for raw in ['2', 'x', '5']:\n    try:\n        print(int(raw) * 2)\n    except ValueError:\n        print('skip')",'4\nskip\n10',['4\n10','2\nskip\n5','skip'],'Each iteration has its own conversion attempt; the middle failure does not end the loop.')
C('An explicit failure signal',"def f(x):\n    if x < 0:\n        raise ValueError('negative')\n    return x * 2\ntry:\n    print(f(-1))\nexcept ValueError as err:\n    print(str(err))",'negative',['-2','ValueError','None'],'The raised exception carries the message negative, printed by the handler.')
C('An off-by-one test','def count(n):\n    return len(range(1, n))\nprint(count(4))','3',['4','5','0'],'range excludes its stop value; it contains 1, 2 and 3.')
C('The cleanup path without failure',"try:\n    print('work')\nexcept RuntimeError:\n    print('error')\nfinally:\n    print('end')",'work\nend',['work','error\nend','end\nwork'],'The try succeeds and skips the handler; finally still executes.')
C('Testing the original list','a = [5, 1, 3]\nb = sorted(a)\nprint(a == b)','False',['True','None','TypeError'],'sorted produces a new ordered list and leaves the original order unchanged.')
C('Regression fixture',"def clamp(x):\n    return min(10, max(0, x))\nprint([clamp(x) for x in [-1, 0, 7, 10, 12]])",'[0, 0, 7, 10, 10]',['[-1, 0, 7, 10, 12]','[0, 0, 10, 10, 10]','[0, 1, 7, 9, 10]'],'Values below zero become zero, values above ten become ten, and interior/end-point values are preserved.')
T('Which input most directly distinguishes x > 10 from x >= 10?', '10','9','11','100','Only the equality boundary yields different Boolean results for these two conditions.')
T('What does one passing test establish?', 'The observed case matched its expectation','The program is correct for every input','The algorithm is optimal','There are no type errors anywhere','A finite observed case supports that case; it does not prove universal correctness.')
T('A test oracle is best described as:', 'An independently justified expected result','The newest actual output copied without review','A timer for the program','A syntax-highlighting tool','An oracle defines what should happen, using the specification, hand calculation, or another justified reference.')
T('Which is a syntax error?', 'An if statement missing its colon','A valid program using the wrong formula','Division by zero during execution','Accessing an absent dictionary key','A missing colon violates the language grammar before normal execution begins.')
T('Which is a logic error?', 'Returning area * 2 when the contract requires area','A missing closing parenthesis','An uncaught IndexError','An invalid indentation token','A logic error can execute normally while returning a result inconsistent with the contract.')
T('For a nonempty-mean function, which boundary should be tested explicitly?', 'An empty collection and a one-item collection','Only one large random collection','Only three positive readings','Only collections already used in the implementation','Empty input checks the stated rejection behavior, and one item checks the smallest valid size.')
T('Why keep a regression test after fixing a bug?', 'To detect a later return of the same failure','To guarantee no unrelated bugs exist','To replace the specification','To force the same runtime on every machine','A regression fixture preserves evidence of a previously failing behavior.')
T('Which handler is usually most informative for a known conversion failure?', 'except ValueError:','except: pass','except BaseException: pass','Removing all handlers','A specific handler addresses the anticipated failure without hiding unrelated defects.')
T('What should happen after a test fails?', 'Compare actual and expected values, then isolate the cause','Immediately replace the expected value with actual output','Delete the test without investigation','Change several unrelated modules at once','A failure is evidence to investigate; either implementation or expectation may need a justified correction.')
T('Why is print debugging useful on a small loop?', 'It reveals selected intermediate values and execution order','It proves the program correct for all inputs','It prevents every exception','It automatically repairs the loop','Selected traces can expose when state first departs from the intended invariant.')
T('Which practice makes a timing comparison fairer?', 'Use equivalent inputs and verify equivalent results','Time one function including file loading and the other excluding it','Compare different output contracts','Use one unrecorded run only','Equivalent work and a stated timing boundary are prerequisites for interpreting a comparison.')
T('Which is a suitable use of an assertion?', 'Checking an internal invariant during development','Replacing all validation of untrusted input','Silently correcting invalid data','Guaranteeing execution even with optimization enabled','Assertions document/check internal assumptions; Python may omit them under optimized execution.')
T('Which statement about finally is correct?', 'It runs on normal exit and while propagating an exception','It runs only when no exception occurs','It runs only if except prints something','It always suppresses exceptions','Cleanup runs even when an exception is not handled. Without an overriding action in finally, the pending exception continues to propagate.')
T('An input parser should normally separate which concerns?', 'Text conversion and domain validation','Variable names and font colors','Expected output and actual output by making them identical','Every operation into a broad silent handler','A string may convert successfully yet represent an invalid physical/domain value.')
T('Which pair checks a lower-bound contract x >= 0 most directly?', '-1 and 0','4 and 5','20 and 30','100 and 101','The pair crosses the rejection boundary and includes its exact valid endpoint.')
T('What is a minimal reproducing example?', 'A small case retaining the failure and necessary setup','The complete project plus unrelated files','A case that no longer fails','A screenshot without inputs','Removing unrelated details makes the causal behavior easier to understand while preserving the fault.')
T('Why compare floating-point calculations using a justified tolerance?', 'Rounding can make mathematically equal expressions differ slightly','All floating-point values are random','A tolerance makes every algorithm correct','Exact equality always raises an exception','Binary floating-point arithmetic can introduce small representation and rounding differences.')
T('Which tolerance policy is meaningful near an expected zero?', 'Include an absolute tolerance appropriate to the units','Use only a relative tolerance and no absolute tolerance','Accept any result with a positive sign','Round every value to an integer','A purely relative criterion against zero offers no nonzero allowance; absolute tolerance supplies a scale.')
T('Which test detects unintended input mutation?', 'Compare the input with an independent saved copy after the call','Assign backup = input and compare the aliases','Check only that the function returns quickly','Print only the function name','A true copy preserves the original content; another name for the same list does not.')
T('A function rejects negative lengths. Which behavior should its test verify?', 'The documented exception for a negative input','An arbitrary numeric result','That every exception is silently ignored','Only that a positive example runs','Invalid-input behavior is part of the contract and deserves an explicit expected exception.')
T('What is the main risk of except: pass around a whole workflow?', 'It can hide unrelated failures and leave invalid state','It makes all calculations faster','It catches only ValueError','It guarantees cleanup','A broad silent catch removes evidence and can allow later code to proceed with incomplete results.')
T('What does branch coverage measure?', 'The proportion of decision outcomes exercised by the tests','Whether every possible input was tested','Whether every numeric result is correct','Whether the code is fastest','Branch coverage records which decision outcomes the tests take. It measures executed structure, not whether the results are correct or all possible inputs have been tested.')
T('Which is a good debugging change strategy?', 'Change one justified cause and rerun relevant tests','Make many speculative changes simultaneously','Remove validation until the output looks plausible','Use a new input for every comparison','Small changes preserve the ability to relate a behavior change to a specific cause.')
T('An exception message should ideally help identify:', 'The failed condition and relevant context','The author’s preferred editor theme','An unrelated successful test','Only a generic word such as error','A precise message makes diagnosis easier without requiring reconstruction of all preceding state.')
T('A calculation passes all supplied examples. What is the next sound claim?', 'Those examples passed under the tested conditions','All future inputs are safe','The model assumptions are physically verified','No review is needed','The claim must remain within the tested cases and assumptions.')
