C('Instance initialization','class Sensor:\n    def __init__(self, value):\n        self.value = value\ns = Sensor(12)\nprint(s.value)','12',['0','None','Sensor'],'The constructor stores the supplied argument on the new instance.')
C('Independent instances','class Box:\n    def __init__(self, x):\n        self.x = x\na, b = Box(2), Box(5)\na.x = 9\nprint(a.x, b.x)','9 5',['9 9','2 5','2 9'],'Each instance has its own x attribute; changing a does not change b.')
C('A bound method','class Scale:\n    def __init__(self, factor):\n        self.factor = factor\n    def apply(self, x):\n        return self.factor * x\nprint(Scale(3).apply(4))','12',['7','3','TypeError'],'The bound call supplies self automatically and multiplies the stored factor by 4.')
C('A method return','class Counter:\n    def __init__(self):\n        self.n = 0\n    def step(self):\n        self.n += 1\nc = Counter()\nprint(c.step(), c.n)','None 1',['1 1','0 1','None 0'],'The method mutates n but has no explicit return, so its result is None.')
C('Aliased object state','class Tank:\n    def __init__(self):\n        self.level = 4\na = Tank()\nb = a\nb.level = 8\nprint(a.level, a is b)','8 True',['4 False','4 True','8 False'],'Both names reference the same Tank object.')
C('Fresh list per instance','class Log:\n    def __init__(self):\n        self.values = []\na, b = Log(), Log()\na.values.append(3)\nprint(a.values, b.values)','[3] []',['[3] [3]','[] []','3 None'],'The list expression runs on each initialization, creating distinct lists.')
C('Shared class list','class Log:\n    values = []\na, b = Log(), Log()\na.values.append(3)\nprint(b.values)','[3]',['[]','3','AttributeError'],'No instance attribute shadows values, so both objects find and mutate the class list.')
C('Class attribute shadowing','class Gauge:\n    unit = "Pa"\na, b = Gauge(), Gauge()\na.unit = "kPa"\nprint(a.unit, b.unit)','kPa Pa',['kPa kPa','Pa Pa','Pa kPa'],'Assigning a.unit creates an instance attribute; b still reads the class attribute.')
C('A getter computes a result','class Rectangle:\n    def __init__(self, w, h):\n        self.w, self.h = w, h\n    def area(self):\n        return self.w * self.h\nprint(Rectangle(3, 5).area())','15',['8','3','None'],'The method combines the two stored dimensions by multiplication.')
C('Two state changes','class Counter:\n    def __init__(self):\n        self.n = 0\n    def add(self, amount):\n        self.n += amount\nc = Counter()\nc.add(2)\nc.add(5)\nprint(c.n)','7',['5','2','0'],'Both calls update the same instance, so the changes accumulate.')
C('Returning a snapshot','class Record:\n    def __init__(self):\n        self.data = [1, 2]\n    def snapshot(self):\n        return self.data.copy()\nr = Record()\nx = r.snapshot()\nx.append(9)\nprint(r.data)','[1, 2]',['[1, 2, 9]','[9]','None'],'The copied list can be changed without changing the stored flat list.')
C('A method reference','class Tool:\n    def value(self):\n        return 6\nt = Tool()\nf = t.value\nprint(f())','6',['None','Tool','TypeError'],'The bound method keeps its receiver even when assigned to another name.')
C('Object type test','class Sensor:\n    pass\ns = Sensor()\nprint(isinstance(s, Sensor))','True',['False','Sensor','None'],'The object was constructed from Sensor, so the instance check succeeds.')
C('Class versus instance','class Sensor:\n    pass\ns = Sensor()\nprint(type(s) is Sensor)','True',['False','None','TypeError'],'type returns the class of the instance, which here is exactly Sensor.')
C('A local variable is separate','class Meter:\n    def __init__(self):\n        self.x = 5\n    def read(self):\n        x = 99\n        return self.x\nprint(Meter().read())','5',['99','None','NameError'],'The local x does not replace the instance attribute self.x.')
C('Resetting state','class Counter:\n    def __init__(self):\n        self.n = 4\n    def reset(self):\n        self.n = 0\nc = Counter()\nc.reset()\nprint(c.n)','0',['4','None','1'],'reset assigns zero to the stored count.')
C('Method delegation','class Sensor:\n    def read(self):\n        return 10\n    def double(self):\n        return 2 * self.read()\nprint(Sensor().double())','20',['10','2','TypeError'],'double calls another method through self and doubles its returned value.')
C('Constructor defaults','class Sample:\n    def __init__(self, value=2):\n        self.value = value\nprint(Sample().value, Sample(7).value)','2 7',['2 2','None 7','7 2'],'The default applies only when the caller omits the value argument.')
C('A formatted representation','class Reading:\n    def __init__(self, x):\n        self.x = x\n    def __str__(self):\n        return f"reading={self.x}"\nprint(Reading(4))','reading=4',['4','Reading(4)','None'],'print uses the string returned by __str__.')
C('Object collection','class Item:\n    def __init__(self, mass):\n        self.mass = mass\nitems = [Item(2), Item(5)]\nprint(sum(x.mass for x in items))','7',['2','5','TypeError'],'The generator reads each object’s mass and sum adds both values.')
C('Constructor validation','class Length:\n    def __init__(self, x):\n        if x < 0:\n            raise ValueError("length")\n        self.x = x\ntry:\n    Length(-1)\nexcept ValueError:\n    print("rejected")','rejected',['-1','None','0'],'Validation fails before a valid initialized Length is returned to the caller.')
C('Mutation through a method','class Box:\n    def __init__(self, x):\n        self.x = x\n    def multiply(self, k):\n        self.x *= k\nb = Box(3)\nb.multiply(4)\nprint(b.x)','12',['3','4','7'],'The augmented assignment updates the instance value to 3 * 4.')
C('Identity comparison','class Box:\n    def __init__(self, x):\n        self.x = x\na, b = Box(3), Box(3)\nprint(a is b, a.x == b.x)','False True',['True True','False False','True False'],'The objects are distinct even though their stored numeric values are equal.')
C('An attribute added later','class Record:\n    pass\nr = Record()\nr.tag = "A"\nprint(r.tag)','A',['None','Record','AttributeError'],'This ordinary class permits assigning a new instance attribute.')
C('A computed temperature','class Temperature:\n    def __init__(self, c):\n        self.c = c\n    def kelvin(self):\n        return self.c + 273.15\nprint(f"{Temperature(20).kelvin():.2f}")','293.15',['20.00','253.15','273.15'],'The conversion adds the Kelvin offset and formats to two decimal places.')
T('What is a class in this introductory model?', 'A definition of an object type with related state and behavior','One particular stored measurement','A loop that always executes once','A replacement for every function','A class describes how instances represent data and expose operations.')
T('What is an instance attribute?', 'State associated with a particular object','A variable shared by every class automatically','A compulsory global variable','A Python keyword','An attribute stored on an instance represents that object’s state.')
T('In an ordinary instance method, what does self refer to?', 'The receiving instance','The parent class in every call','The Python interpreter','A copy of every argument','A bound call passes the receiver as the method’s first argument, conventionally named self.')
T('What is the main purpose of __init__?', 'Initialize the newly created instance','Return a replacement class','Run automatically after every method','Delete the object','__init__ establishes initial state after instance creation and must return None.')
T('Which call correctly invokes an instance method read on s?', 's.read()','read.s()','s.read','class.read(s) with class used as a keyword','Parentheses invoke the bound method; s.read alone retrieves the method object.')
T('Two instances should keep independent measurement histories. Where should each history be created?', 'self.history = [] inside __init__','history = [] only in the class body','One shared global list','As the default argument history=[] reused by every call','Creating a list during each initialization gives each object its own mutable history.')
T('What does b = a do when a is an object?', 'Creates another reference to the same object','Deep-copies every attribute','Calls the constructor again','Converts the object to a class','Assignment binds a name; it does not duplicate the object.')
T('Which is a method’s public interface?', 'Its documented callable behavior and contract','Every temporary local variable','The editor’s line numbers','Only its execution time','Clients should depend on the documented operations, inputs, results and failure behavior.')
T('Why group a value and its unit in one object?', 'To keep related state and operations consistent','To remove the need for dimensional reasoning','To make all units interchangeable','To ensure every measurement is accurate','Encapsulation can centralize conversions and checks, while the programmer still supplies a correct unit model.')
T('A method changes state and has no return statement. Its call returns:', 'None','The receiving object automatically','The last assigned value automatically','True automatically','Python functions and methods return None when execution reaches the end without an explicit return.')
T('Which design best supports an invariant that length is nonnegative?', 'Validate construction and every public state-changing operation','Validate only one example in a notebook','Allow arbitrary public writes while assuming they never happen','Catch every exception and continue','The invariant must be protected at each supported entry point that can establish or change the value.')
T('What is a class attribute useful for?', 'A shared setting or constant associated with the type','A guaranteed independent mutable list for each object','A substitute for every method parameter','An automatically private field','Class attributes provide defaults/shared information; mutable shared state requires care.')
T('Why prefer a method that computes area from width and height over a stale stored area?', 'It derives the result from current dimensions','It guarantees constant physical accuracy','It prevents all mutation automatically','It makes multiplication unnecessary','A derived property avoids maintaining a redundant value after dimension changes.')
T('Which distinguishes object identity from equal data?', 'Distinct objects can contain equal values','Equal values require the same identity','is compares every attribute recursively','Identity changes on every attribute assignment','Identity asks whether references name the same object; value comparisons ask a different question.')
T('Which operation can expose mutable internal state?', 'Returning the original internal list','Returning a numeric mean','Returning a copied flat list','Returning a descriptive string','A caller holding the original list can mutate state without using the intended interface.')
T('What does calling a bound method supply automatically?', 'The instance receiver','Every optional argument','A deep copy of the instance','A new class definition','The receiver is bound; remaining required arguments must still be supplied.')
T('What is composition?', 'An object contains or uses another object','Every class inherits from all others','A function can only return numbers','A method changes its own source','Composition models a has-a relationship and can reuse behavior through contained objects.')
T('A sensor object models a real sensor. Which claim is sound?', 'The model represents selected state and behavior under assumptions','The object guarantees hardware accuracy','The object eliminates calibration needs','A successful constructor certifies physical safety','Software models capture selected contracts; physical validity requires separate evidence.')
T('Which method is a query rather than a state-changing command?', 'mean() returning the current average without modifying history','append_reading(x) adding a sample','reset() clearing the log','set_limit(x) updating a limit','A query observes state, while a command changes it under the declared contract.')
T('What is a useful unit test for two new Counter objects?', 'Advance one and verify the other remains unchanged','Compare only their class names','Advance both and inspect neither','Assume independent state because names differ','This test directly detects accidentally shared mutable state.')
T('Why document whether a method mutates the receiver?', 'Callers need to predict subsequent state','Mutation always raises an exception','Every method is required to mutate','Documentation changes Python binding rules','Mutation is observable behavior and therefore part of the interface contract.')
T('What does obj.method without parentheses usually produce?', 'A bound method object','The method’s returned numeric result','A new instance of obj','A syntax error','Attribute access retrieves the method; a following call expression executes it.')
T('An ordinary local variable x inside a method differs from self.x because:', 'x is local to the call while self.x belongs to the receiver','Both names always reference the same storage','self.x is always global','x persists on the object automatically','Attribute qualification explicitly accesses object state rather than the local namespace.')
T('Which constructor signature avoids a shared mutable default?', 'def __init__(self, values=None):','def __init__(self, values=[]):','def __init__(self, values={}):','def __init__(self, values=set()):','Use None as a sentinel and create/copy the desired collection inside the constructor.')
T('When is a small ordinary function often appropriate?', 'The operation needs no persistent object state','Every operation requires inheritance','Whenever classes exist elsewhere in the project','Only when Python cannot define a class','Choose the simpler abstraction matching the state and behavior needed.')
