C('An inherited method','class Base:\n    def read(self):\n        return 5\nclass Child(Base):\n    pass\nprint(Child().read())','5',['None','0','AttributeError'],'Child inherits read because it supplies no override.')
C('Overriding a method','class Base:\n    def read(self):\n        return 5\nclass Child(Base):\n    def read(self):\n        return 9\nprint(Child().read())','9',['5','14','None'],'Method lookup selects the override defined by Child.')
C('Calling a base constructor','class Base:\n    def __init__(self, x):\n        self.x = x\nclass Child(Base):\n    def __init__(self, x):\n        super().__init__(x)\n        self.y = 2\nc = Child(7)\nprint(c.x + c.y)','9',['7','2','AttributeError'],'super initialization sets x before the child stores y.')
C('Subtype checks','class A:\n    pass\nclass B(A):\n    pass\nb = B()\nprint(isinstance(b, A), type(b) is A)','True False',['True True','False False','False True'],'A B instance is also an A instance, but its exact type is B.')
C('Dynamic dispatch','class Base:\n    def value(self):\n        return 2\n    def report(self):\n        return self.value() * 3\nclass Child(Base):\n    def value(self):\n        return 5\nprint(Child().report())','15',['6','5','10'],'The inherited report calls self.value, which resolves to the child override.')
C('An inherited setting','class A:\n    limit = 10\nclass B(A):\n    pass\nprint(B.limit)','10',['0','None','AttributeError'],'Class attribute lookup continues to the base class.')
C('Subclass shadowing','class A:\n    limit = 10\nclass B(A):\n    limit = 20\nprint(A.limit, B.limit)','10 20',['20 20','10 10','20 10'],'The subclass defines its own limit without changing A.limit.')
C('Validated state update','class Gauge:\n    def __init__(self):\n        self._x = 4\n    def set(self, x):\n        if x < 0:\n            raise ValueError("negative")\n        self._x = x\ng = Gauge()\ntry:\n    g.set(-1)\nexcept ValueError:\n    pass\nprint(g._x)','4',['-1','0','None'],'Validation occurs before assignment, so the rejected update leaves the old state intact.')
C('A read-only property','class Meter:\n    def __init__(self, x):\n        self._x = x\n    @property\n    def value(self):\n        return self._x * 2\nprint(Meter(3).value)','6',['3','None','TypeError'],'Property access invokes the getter without a call at the access site.')
C('Public interface delegation','class Log:\n    def __init__(self):\n        self._xs = []\n    def add(self, x):\n        self._xs.append(x)\n    def count(self):\n        return len(self._xs)\nl = Log()\nl.add(2)\nl.add(8)\nprint(l.count())','2',['10','8','0'],'Two add calls append two entries; count reports entries rather than their sum.')
C('Base method extension','class A:\n    def text(self):\n        return "A"\nclass B(A):\n    def text(self):\n        return super().text() + "B"\nprint(B().text())','AB',['B','A','BA'],'The override extends the base result by concatenating B after A.')
C('A shared inherited list','class A:\n    tags = []\nclass B(A):\n    pass\nB.tags.append("x")\nprint(A.tags)','[\'x\']',['[]','x','AttributeError'],'B.tags finds the same list stored on A; append mutates that shared object.')
C('Rebinding an inherited attribute','class A:\n    limit = 10\nclass B(A):\n    pass\nB.limit = 30\nprint(A.limit, B.limit)','10 30',['30 30','10 10','30 10'],'Assignment creates B.limit, leaving the numeric A.limit binding unchanged.')
C('Per-instance override of a default','class Sensor:\n    unit = "Pa"\ns = Sensor()\ns.unit = "bar"\nSensor.unit = "kPa"\nprint(s.unit, Sensor().unit)','bar kPa',['kPa kPa','bar Pa','Pa bar'],'s has its own unit; the new instance reads the updated class default.')
C('An explicit equality policy','class Sample:\n    def __init__(self, x):\n        self.x = x\n    def __eq__(self, other):\n        return isinstance(other, Sample) and self.x == other.x\nprint(Sample(3) == Sample(3))','True',['False','3','TypeError'],'The supplied equality method compares the stored values for Sample instances.')
