C('Duck typing','class A:\n    def read(self):\n        return 2\nclass B:\n    def read(self):\n        return 7\nprint(sum(x.read() for x in [A(), B()]))','9',['2','7','TypeError'],'Both objects support the required method even though neither inherits from the other.')
C('Base initialization omitted','class A:\n    def __init__(self):\n        self.x = 5\nclass B(A):\n    def __init__(self):\n        self.y = 2\nb = B()\nprint(hasattr(b, "x"))','False',['True','5','AttributeError'],'Defining B.__init__ replaces inherited initialization; it does not automatically call A.__init__.')
C('A subclass relationship','class A:\n    pass\nclass B(A):\n    pass\nprint(issubclass(B, A), issubclass(A, B))','True False',['True True','False True','False False'],'B derives from A, while the reverse relationship is absent.')
C('Shared counter through explicit class access','class Item:\n    created = 0\n    def __init__(self):\n        Item.created += 1\na = Item()\nb = Item()\nprint(Item.created)','2',['0','1','3'],'Each constructor increments the same class attribute explicitly.')
C('Name-mangled storage through a getter','class Box:\n    def __init__(self):\n        self.__x = 6\n    def get(self):\n        return self.__x\nprint(Box().get())','6',['None','0','AttributeError'],'The matching definition/access inside Box use the same name-mangled attribute.')
C('Information hiding by convention','class Box:\n    def __init__(self):\n        self._x = 3\nb = Box()\nb._x = 8\nprint(b._x)','8',['3','AttributeError','None'],'A single leading underscore is a nonpublic-use convention, not an enforced access barrier.')
