C('Copies retained by slicing','xs = [1, 2, 3, 4]\nys = xs[1:]\nys[0] = 9\nprint(xs, ys)','[1, 2, 3, 4] [9, 3, 4]',['[1, 9, 3, 4] [9, 3, 4]','[1, 2, 3, 4] [2, 3, 4]','[9, 3, 4] [9, 3, 4]'],'Slicing creates a new outer list; replacing a scalar entry does not alter the original list.')
C('Front removal shifts the sequence','xs = [4, 5, 6]\ny = xs.pop(0)\nprint(y, xs)','4 [5, 6]',['6 [4, 5]','0 [4, 5, 6]','4 [4, 5, 6]'],'pop(0) returns the first element and removes it, shifting remaining elements left.')
C('Fresh list concatenation','xs = [1, 2]\nys = xs + [3]\nprint(xs, ys)','[1, 2] [1, 2, 3]',['[1, 2, 3] [1, 2, 3]','[1, 2] [3]','None [1, 2, 3]'],'+ constructs a new list containing both sequences and leaves xs unchanged.')
C('Every complete window','xs = [2, 4, 8, 10]\nw = 2\nprint([sum(xs[i:i+w]) / w for i in range(len(xs)-w+1)])','[3.0, 6.0, 9.0]',['[3.0, 6.0]','[2.0, 4.0, 8.0, 10.0]','[3.0, 9.0]'],'A width-two window starts at 0, 1 and 2; all three complete windows are returned.')
C('Running subtotal update','total = 2 + 4 + 8\ntotal += 10 - 2\nprint(total)','22',['14','24','20'],'Drop the outgoing 2 and add the incoming 10 to update the subtotal.')
C('Recursive factorial count','calls = 0\ndef f(n):\n    global calls\n    calls += 1\n    return 1 if n == 0 else n * f(n-1)\nprint(f(4), calls)','24 5',['24 4','24 24','5 24'],'The calls are for n = 4, 3, 2, 1 and 0, including the base case.')
C('Fibonacci convention','def f(n):\n    return 1 if n < 2 else f(n-1) + f(n-2)\nprint([f(i) for i in range(6)])','[1, 1, 2, 3, 5, 8]',['[0, 1, 1, 2, 3, 5]','[1, 2, 3, 5, 8, 13]','[1, 1, 1, 1, 1, 1]'],'This explicitly uses F(0) = F(1) = 1, then adds the two preceding values.')
C('Naive recursive calls','calls = 0\ndef f(n):\n    global calls\n    calls += 1\n    return 1 if n < 2 else f(n-1) + f(n-2)\nprint(f(4), calls)','5 9',['5 5','3 9','5 4'],'The call-count recurrence is C(0)=C(1)=1 and C(n)=1+C(n-1)+C(n-2), giving C(4)=9.')
C('A warm cache','cache = {0: 1, 1: 1, 2: 2, 3: 3}\nhits = 0\ndef f(n):\n    global hits\n    if n in cache:\n        hits += 1\n        return cache[n]\n    cache[n] = f(n-1) + f(n-2)\n    return cache[n]\nprint(f(3), hits)','3 1',['3 0','3 3','2 1'],'The requested result is already cached, so one lookup hit avoids recursive expansion.')
C('Full-width window','xs = [2, 4, 6]\nw = len(xs)\nprint([sum(xs[i:i+w])/w for i in range(len(xs)-w+1)])','[4.0]',['[]','[2.0, 4.0, 6.0]','4.0'],'There is exactly one complete window when width equals the record length.')
C('Width-one windows','xs = [3, 7, 9]\nprint([sum(xs[i:i+1])/1 for i in range(len(xs))])','[3.0, 7.0, 9.0]',['[3, 7]','[19.0]','[]'],'Each complete window contains one value, and / produces float results.')
C('Scalar work in a chain','def total(xs):\n    if not xs:\n        return 0\n    return xs[0] + total(xs[1:])\nprint(total([2, 3, 5]))','10',['5','0','235'],'The returned sum is correct for this input, while the slices introduce additional copying work.')
C('Repeated prefix lengths','n = 5\nprint(sum(len(list(range(i))) for i in range(n)))','10',['25','15','5'],'The constructed lengths are 0 through 4; total copied/created entries sum to 10.')
