C('Engineering units','force_n, area_m2 = 120, 0.004\nprint(force_n / area_m2)','30000.0',['0.000033333333333333335','480.0','30.0'],'Stress is force divided by area: 120 / 0.004 = 30000 pascals.')
C('Combined filtering and averaging','xs = [-2, 4, 8, -1, 6]\nvalid = [x for x in xs if x >= 0]\nprint(sum(valid) / len(valid))','6.0',['3.0','18.0','5.0'],'Only 4, 8 and 6 are retained; their average is 18 / 3.')
C('Parsing and checking a record',"raw = [' 2 ', '4', 'bad', '6']\nvalues = []\nfor s in raw:\n    try:\n        values.append(float(s.strip()))\n    except ValueError:\n        pass\nprint(len(values), sum(values))",'3 12.0',['4 12.0','3 246.0','4 0.0'],'Three strings convert successfully, and their float sum is 12.0; the policy here skips conversion failures.')
C('Dictionary accumulation',"counts = {}\nfor tag in ['A', 'B', 'A', 'C', 'A']:\n    counts[tag] = counts.get(tag, 0) + 1\nprint(counts['A'], len(counts))",'3 3',['3 5','2 3','1 5'],'A occurs three times, and there are three distinct tags.')
C('A stopping criterion','error = 1.0\nsteps = 0\nwhile error > 0.1:\n    error /= 2\n    steps += 1\nprint(steps)','4',['3','5','10'],'The errors are 0.5, 0.25, 0.125 and 0.0625; only the fourth update crosses the threshold.')
C('A bisection update','lo, hi = 0.0, 2.0\nmid = (lo+hi)/2\nif mid*mid < 2:\n    lo = mid\nelse:\n    hi = mid\nprint(lo, hi)','1.0 2.0',['0.0 1.0','1.0 1.0','0.0 2.0'],'At mid=1, the square is below 2, so the lower endpoint moves to 1.')
C('Recursive sum','def total(xs):\n    if not xs:\n        return 0\n    return xs[0] + total(xs[1:])\nprint(total([3, -1, 5]))','7',['9','5','0'],'The recursion adds 3, -1 and 5, then terminates on the empty list.')
C('A function without side effects','def shifted(xs):\n    return [x+1 for x in xs]\na = [2, 4]\nb = shifted(a)\nprint(a, b)','[2, 4] [3, 5]',['[3, 5] [3, 5]','[2, 4] [2, 4]','None [3, 5]'],'The comprehension builds a new list rather than modifying a.')
C('Shallow-copy review','a = [[2], [3]]\nb = a[:]\nb[1][0] = 8\nprint(a)','[[2], [8]]',['[[2], [3]]','[[8], [3]]','[[8], [8]]'],'The outer lists differ but their inner lists are shared.')
C('Sorting structured results','rows = [{"name":"A", "cost":7}, {"name":"B", "cost":4}]\nprint(sorted(rows, key=lambda r:r["cost"])[0]["name"])','B',['A','4','KeyError'],'Sorting by cost puts the lower-cost B record first.')
C('Exception plus final report',"try:\n    value = float('oops')\nexcept ValueError:\n    value = None\nprint(value is None)",'True',['False','oops','ValueError'],'The explicit missing-value policy assigns None after conversion fails.')
C('Validation of finite measurements','import math\nxs = [1.0, float("inf"), -2.0, float("nan")]\nprint(sum(math.isfinite(x) for x in xs))','2',['4','3','1'],'Only 1.0 and -2.0 are finite; sign alone does not determine finiteness.')
C('Recursion and base cases','def f(n):\n    if n <= 1:\n        return 1\n    return n*f(n-1)\nprint(f(1), f(4))','1 24',['0 24','1 12','1 4'],'The declared base case returns one; the second call multiplies 4 * 3 * 2 * 1.')
C('Default dictionary values',"readings = {'A': [2, 4], 'B': [6]}\nprint(len(readings.get('C', [])))",'0',['1','2','KeyError'],'The absent key uses an empty-list default, whose length is zero.')
C('An inclusive alarm threshold','xs = [49, 50, 51]\nprint([x for x in xs if x >= 50])','[50, 51]',['[51]','[49, 50]','[49, 50, 51]'],'The stated >= condition includes the exact threshold value.')
C('Rounding at presentation time','x = 10 / 3\nprint(f"{x:.2f}", x > 3.33)','3.33 True',['3.33 False','3.34 True','3.3 True'],'Formatting changes the displayed representation, not the underlying x used by the comparison.')
C('Cumulative object state','class Total:\n    def __init__(self):\n        self.x = 0\n    def add(self, x):\n        self.x += x\nt = Total()\nfor x in [2, -1, 5]:\n    t.add(x)\nprint(t.x)','6',['5','8','0'],'The same instance accumulates all three signed updates.')
C('Reviewing dynamic dispatch','class Sensor:\n    def read(self):\n        return 4\nclass Scaled(Sensor):\n    def read(self):\n        return 3*super().read()\nprint(Scaled().read())','12',['4','7','None'],'The override obtains the base reading and multiplies it by three.')
C('Search after preparation','from bisect import bisect_left\na = sorted([9, 2, 6])\ni = bisect_left(a, 6)\nprint(a[i], i)','6 1',['6 2','2 0','9 2'],'After sorting, the list is [2, 6, 9], so 6 is at index 1.')
C('Data retention policy','rows = [(0, 10), (1, None), (2, 14)]\nkept = [(t,x) for t,x in rows if x is not None]\nprint(kept)','[(0, 10), (2, 14)]',['[(0, 10), (1, 14)]','[(0, 10), (1, None), (2, 14)]','[(0, 10), (2, 0)]'],'Filtering removes the missing record while preserving original timestamps on the retained rows.')
C('Whole-workflow accounting','prepare = 100\nqueries = 20\nper_query = 3\nprint(prepare + queries*per_query)','160',['60','2000','123'],'Total work includes the one-time preparation plus all twenty query costs.')
